// Una entrada por marca. eventos: eventos de GA4 que quieres ver (nombre → etiqueta del reporte).
const MARCAS = [
  { marca: 'marca-a', nombre: 'Marca A', ga4: '__GA4_PROPIEDAD_A__', gsc: '__GSC_SITIO_A__', eventos: { generate_lead: 'Leads', form_submit: 'Formularios enviados' } },
  { marca: 'marca-b', nombre: 'Marca B', ga4: '__GA4_PROPIEDAD_B__', gsc: '__GSC_SITIO_B__', eventos: { generate_lead: 'Leads', form_submit: 'Formularios enviados' } },
];
const hoy = $now.setZone('America/Mexico_City').startOf('day');
const d = n => hoy.minus({ days: n }).toISODate();
const fechas = { actual: { ini: d(7), fin: d(1) }, anterior: { ini: d(14), fin: d(8) }, gsc: { ini: d(9), fin: d(3), desde: d(16) } };
const rangos = [{ startDate: '7daysAgo', endDate: 'yesterday', name: 'actual' }, { startDate: '14daysAgo', endDate: '8daysAgo', name: 'anterior' }];
return MARCAS.map(m => ({ json: Object.assign({}, m, { fechas,
  ga4_url: 'https://analyticsdata.googleapis.com/v1beta/properties/' + m.ga4 + ':batchRunReports',
  ga4_body: { requests: [
    { dateRanges: rangos, metrics: [{ name: 'activeUsers' }, { name: 'sessions' }, { name: 'engagementRate' }] },
    { dateRanges: rangos, dimensions: [{ name: 'eventName' }], metrics: [{ name: 'eventCount' }], dimensionFilter: { filter: { fieldName: 'eventName', inListFilter: { values: Object.keys(m.eventos) } } } },
    { dateRanges: [rangos[0]], dimensions: [{ name: 'sessionDefaultChannelGroup' }], metrics: [{ name: 'sessions' }], orderBys: [{ metric: { metricName: 'sessions' }, desc: true }], limit: 6 },
    { dateRanges: [rangos[0]], dimensions: [{ name: 'landingPage' }], metrics: [{ name: 'sessions' }], orderBys: [{ metric: { metricName: 'sessions' }, desc: true }], limit: 5 },
  ] },
  gsc_url: 'https://www.googleapis.com/webmasters/v3/sites/' + encodeURIComponent(m.gsc) + '/searchAnalytics/query',
}) }));

const M = $('Marcas').all().map(i => i.json);
const GA = $('GA4').all().map(i => i.json || {}), GD = $('GSC por día').all().map(i => i.json || {}), GQ = $('GSC búsquedas').all().map(i => i.json || {});
const META = { 'marca-a': 'Meta Ads A', 'marca-b': 'Meta Ads B' };
const e = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const num = n => Number(n || 0).toLocaleString('es-MX', { maximumFractionDigits: 0 });
const pesos = n => '$' + num(n);
const pct = (a, b) => (b ? Math.round(((a - b) / b) * 100) : null);
const delta = (a, b) => { const p = pct(a, b); return p === null ? '' : ` (${p >= 0 ? '▲' : '▼'}${Math.abs(p)}%)`; };
const corta = d => { const [, m, dd] = d.split('-'); return `${Number(dd)} ${['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'][Number(m) - 1]}`; };
const errorDe = j => j && j.error ? (j.error.message || j.error.status || 'error') : '';
return M.map((m, i) => {
  const f = m.fechas, alertas = [];
  let t = `📊 <b>Reporte semanal · ${e(m.nombre)}</b>\n${corta(f.actual.ini)}–${corta(f.actual.fin)}, contra la semana anterior\n\n<b>Sitio (GA4)</b>\n`;
  const g = GA[i] || {};
  if (errorDe(g) || !g.reports) t += `⚠️ No se pudo leer: ${e(errorDe(g) || 'sin datos')}\n`;
  else {
    const [tot, evs, ch, pg] = g.reports;
    const T = { actual: {}, anterior: {} };
    const hdr = (tot.metricHeaders || []).map(h => h.name);
    for (const r of tot.rows || []) { const k = r.dimensionValues.at(-1).value; if (T[k]) hdr.forEach((h, j) => (T[k][h] = Number(r.metricValues[j].value))); }
    const ev = { actual: {}, anterior: {} };
    for (const r of evs.rows || []) { const k = r.dimensionValues.at(-1).value; if (ev[k]) ev[k][r.dimensionValues[0].value] = Number(r.metricValues[0].value); }
    const a = T.actual, b = T.anterior;
    t += `Usuarios ${num(a.activeUsers)}${delta(a.activeUsers, b.activeUsers)} · Sesiones ${num(a.sessions)}${delta(a.sessions, b.sessions)}\n`;
    t += Object.entries(m.eventos).map(([k, lbl]) => `${e(lbl)} ${num(ev.actual[k])}${delta(ev.actual[k] || 0, ev.anterior[k] || 0)}`).join(' · ') + '\n';
    const canales = (ch.rows || []).map(r => `${e(r.dimensionValues[0].value)} ${num(r.metricValues[0].value)}`);
    const paginas = (pg.rows || []).map(r => `${e(r.dimensionValues[0].value)} ${num(r.metricValues[0].value)}`);
    if (canales.length) t += 'Canales: ' + canales.join(', ') + '\n';
    if (paginas.length) t += 'Páginas de entrada: ' + paginas.join(', ') + '\n';
    if (b.sessions >= 30 && pct(a.sessions, b.sessions) <= -30) alertas.push(`Las sesiones bajaron ${Math.abs(pct(a.sessions, b.sessions))}%.`);
    if (!a.sessions) alertas.push('GA4 no registró visitas: revisa la etiqueta del sitio.');
  }
  t += `\n<b>Google orgánico</b> (${corta(f.gsc.ini)}–${corta(f.gsc.fin)})\n`;
  const d = GD[i] || {}, q = GQ[i] || {};
  if (errorDe(d)) t += `⚠️ No se pudo leer: ${e(errorDe(d))}\n`;
  else {
    const s = { actual: { c: 0, i: 0, p: 0 }, anterior: { c: 0, i: 0, p: 0 } };
    for (const r of d.rows || []) { const k = r.keys[0] >= f.gsc.ini ? 'actual' : 'anterior'; s[k].c += r.clicks; s[k].i += r.impressions; s[k].p += r.position * r.impressions; }
    const a = s.actual, b = s.anterior;
    t += `Clics ${num(a.c)}${delta(a.c, b.c)} · Impresiones ${num(a.i)}${delta(a.i, b.i)}` + (a.i ? ` · Posición media ${(a.p / a.i).toFixed(1)}` : '') + '\n';
    const busq = (q.rows || []).slice(0, 5).map(r => `«${e(r.keys[0])}» ${r.clicks} clics/${num(r.impressions)} imp`);
    t += busq.length ? 'Búsquedas: ' + busq.join(', ') + '\n' : 'Todavía sin búsquedas registradas.\n';
  }
  t += '\n<b>Meta Ads</b>\n';
  let mj = {}; try { mj = $(META[m.marca]).first().json || {}; } catch (err) { mj = { error: { message: 'no corrió' } }; }
  if (errorDe(mj)) t += `⚠️ No se pudo leer: ${e(errorDe(mj))}\n`;
  else {
    const out = {};
    for (const r of mj.data || []) {
      const k = r.date_start === f.actual.ini ? 'actual' : r.date_start === f.anterior.ini ? 'anterior' : null;
      if (!k) continue;
      const acc = {}; for (const x of r.actions || []) acc[x.action_type] = Number(x.value);
      out[k] = { gasto: Number(r.spend || 0), clics: Number(r.inline_link_clicks || r.clicks || 0), leads: acc['lead'] ?? acc['offsite_conversion.fb_pixel_lead'] ?? acc['onsite_conversion.lead_grouped'] ?? 0 };
    }
    const a = out.actual, b = out.anterior || {};
    if (!a || !a.gasto) t += 'Sin gasto esta semana.\n';
    else {
      t += `Gasto ${pesos(a.gasto)}${delta(a.gasto, b.gasto)} · Clics ${num(a.clics)} · Leads ${num(a.leads)}` + (a.leads ? ` · Costo por lead ${pesos(a.gasto / a.leads)}` : '') + '\n';
      if (!a.leads && a.gasto >= 500) alertas.push(`Meta gastó ${pesos(a.gasto)} sin leads registrados.`);
    }
  }
  if (alertas.length) t += '\n🚨 ' + alertas.join('\n🚨 ');
  return { json: { marca: m.marca, texto: t.trim() } };
});
